def next_smallest_palindrome(num: int) -> int:
    def is_all_nines(s: str) -> bool:
        return all(ch == '9' for ch in s)

    s = str(num)
    length = len(s)

    # If all digits are 9, next palindrome is 10..01 (length+1)
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Otherwise, find next palindrome strictly greater than num
    # Strategy:
    # 1. Mirror the left half to the right half.
    # 2. If palindrome <= num, increment the middle and propagate carry if needed.
    # 3. Construct palindrome again.

    half = length // 2
    odd = (length % 2 != 0)

    left = s[:half]
    middle = s[half] if odd else ''
    right = s[half+1:] if odd else s[half:]

    # Build palindrome by mirroring left and middle
    if odd:
        palindrome = left + middle + left[::-1]
    else:
        palindrome = left + left[::-1]

    if int(palindrome) > num:
        return int(palindrome)

    # Need to increment the middle part
    if odd:
        # Increment middle digit
        middle_int = int(middle)
        middle_int += 1
        if middle_int <= 9:
            # Just update middle and rebuild palindrome
            new_middle = str(middle_int)
            return int(left + new_middle + left[::-1])
        else:
            # Middle digit overflows, becomes 0, need to increment left part
            middle = '0'
            # Increment left part as number
            left_int = int(left) if left else 0
            left_int += 1
            left = str(left_int).rjust(len(left), '0')  # preserve length
            return int(left + middle + left[::-1])
    else:
        # Even length - increment left part and mirror
        left_int = int(left) if left else 0
        left_int += 1
        left = str(left_int).rjust(len(left), '0')
        return int(left + left[::-1])

