def min_Jumps(x: int, y: int, jump_length: float) -> int:
    dist = math.hypot(x, y)
    if dist == 0:
        return 0
    if dist == jump_length:
        return 1
    if dist < jump_length:
        return 2
    return math.ceil(dist / jump_length)

